<div class="modal fade" id="confirmActionModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content border-0" style="border-radius:18px;box-shadow:0 20px 60px #24155b2b"><div class="modal-body text-center p-4 p-md-5"><div id="confirmActionIcon" class="mx-auto mb-3" style="width:58px;height:58px;border-radius:50%;display:grid;place-items:center;background:#f0edff;color:#6d4aff;font-size:23px"><i class="fa-solid fa-circle-question"></i></div><h5 id="confirmActionTitle" class="fw-bold mb-2">Konfirmasi tindakan</h5><p id="confirmActionMessage" class="text-secondary mb-4">Apakah Anda yakin ingin melanjutkan?</p><div class="d-flex justify-content-center gap-2"><button type="button" class="btn btn-light px-4" data-bs-dismiss="modal">Batal</button><button type="button" id="confirmActionSubmit" class="btn btn-primary px-4">Ya, lanjutkan</button></div></div></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>
document.addEventListener('DOMContentLoaded',function(){const e=document.getElementById('confirmActionModal');if(!e)return;const m=bootstrap.Modal.getOrCreateInstance(e),b=document.getElementById('confirmActionSubmit'),i=document.getElementById('confirmActionIcon');let f=null;document.querySelectorAll('[data-confirm-action]').forEach(x=>x.addEventListener('submit',function(t){if(x.dataset.confirmed==='true'){x.dataset.confirmed='';return}t.preventDefault();f=x;document.getElementById('confirmActionTitle').textContent=x.dataset.confirmTitle||'Konfirmasi tindakan';document.getElementById('confirmActionMessage').textContent=x.dataset.confirmMessage||'Apakah Anda yakin ingin melanjutkan?';const d=x.dataset.confirmTone==='danger';i.style.background=d?'#fff0f1':'#f0edff';i.style.color=d?'#dc3545':'#6d4aff';i.innerHTML=d?'<i class="fa-solid fa-trash-can"></i>':'<i class="fa-solid fa-circle-question"></i>';b.className='btn px-4 '+(d?'btn-danger':'btn-primary');b.textContent=d?'Ya, hapus data':'Ya, simpan';m.show()}));b.addEventListener('click',function(){if(!f)return;f.dataset.confirmed='true';m.hide();f.requestSubmit()})});
</script>@stack('scripts')</body></html>
